import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.nkraVhM_.js";var i=JSON.parse(`{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1785319710000}`),a={name:`guide/introduction.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h1><h2 id="about-sudoku" tabindex="-1">About Sudoku <a class="header-anchor" href="#about-sudoku" aria-label="Permalink to “About Sudoku”">​</a></h2><p><strong>Sudoku — The Classic Number Puzzle, Perfectly Made.</strong></p><p><img src="/screenshot-ipad-main.png" alt="Sudoku running on iPad"></p><p>Rediscover the timeless logic puzzle you love, refined for modern devices with smooth controls, beautiful themes, and endless replayability. Whether you are a first-time player or a seasoned expert, this is the Sudoku experience you have been waiting for.</p><h2 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to “Core Features”">​</a></h2><h3 id="🔢-authentic-gameplay" tabindex="-1">🔢 <strong>Authentic Gameplay</strong> <a class="header-anchor" href="#🔢-authentic-gameplay" aria-label="Permalink to “🔢 Authentic Gameplay”">​</a></h3><p>True to the classic rules — fill a 9×9 grid so that every row, column, and 3×3 box contains digits 1 through 9 exactly once. Tap to place numbers, use pencil notes for candidates, and let logic guide you to the solution.</p><h3 id="🎯-5-difficulty-levels" tabindex="-1">🎯 <strong>5 Difficulty Levels</strong> <a class="header-anchor" href="#🎯-5-difficulty-levels" aria-label="Permalink to “🎯 5 Difficulty Levels”">​</a></h3><p>Five carefully calibrated difficulties with different numbers of given cells:</p><table tabindex="0"><thead><tr><th>Level</th><th>Given Cells</th><th>Description</th></tr></thead><tbody><tr><td>Easy</td><td>45</td><td>Great for beginners and quick games</td></tr><tr><td>Medium</td><td>36</td><td>A balanced challenge for casual players</td></tr><tr><td>Hard</td><td>31</td><td>Requires logical deduction techniques</td></tr><tr><td>Expert</td><td>27</td><td>For experienced solvers who want a real test</td></tr><tr><td>Master</td><td>24</td><td>The ultimate challenge — only for the bravest</td></tr></tbody></table><p>Each puzzle is uniquely generated — no two games are ever the same.</p><h3 id="📱-universal-app" tabindex="-1">📱 <strong>Universal App</strong> <a class="header-anchor" href="#📱-universal-app" aria-label="Permalink to “📱 Universal App”">​</a></h3><p>One purchase works on iPhone, iPad, and Mac. Native controls for each platform — touch gestures on iOS, mouse and keyboard on Mac. Your progress syncs via iCloud across all your devices.</p><p><img src="/screenshot-iphone-main.png" alt="Sudoku on iPhone"></p><p><img src="/screenshot-mac-difficulty.png" alt="Sudoku on Mac"></p><h3 id="💡-hints-notes" tabindex="-1">💡 <strong>Hints &amp; Notes</strong> <a class="header-anchor" href="#💡-hints-notes" aria-label="Permalink to “💡 Hints &amp; Notes”">​</a></h3><ul><li><strong>Hint</strong>: Stuck? Get a hint that reveals one correct cell without spoiling the whole puzzle.</li><li><strong>Pencil (Notes)</strong>: Toggle pencil mode to jot down candidate digits in empty cells. Pencil marks in peer cells (same row/column/box) auto-clear when you place a number.</li><li><strong>Error Checking</strong>: Optional highlighting of incorrect entries so you can learn from mistakes.</li><li><strong>Undo</strong>: Full undo support — take back any move, anytime.</li></ul><h3 id="🏆-daily-challenge" tabindex="-1">🏆 <strong>Daily Challenge</strong> <a class="header-anchor" href="#🏆-daily-challenge" aria-label="Permalink to “🏆 Daily Challenge”">​</a></h3><p>A fresh puzzle every day at the Master difficulty level. Build a streak and track your daily progress on the calendar view in Statistics.</p><h3 id="📊-statistics" tabindex="-1">📊 <strong>Statistics</strong> <a class="header-anchor" href="#📊-statistics" aria-label="Permalink to “📊 Statistics”">​</a></h3><p>Track your performance: total games played, win rate, current streak, best streak, and per-difficulty breakdowns including best times and averages. Synced via iCloud.</p><h3 id="🎨-8-beautiful-themes" tabindex="-1">🎨 <strong>8 Beautiful Themes</strong> <a class="header-anchor" href="#🎨-8-beautiful-themes" aria-label="Permalink to “🎨 8 Beautiful Themes”">​</a></h3><p>Personalize your board with eight handcrafted color themes: Classic, Midnight, Paper, Forest, Ocean, Sunset, Lavender, and Rose. Each theme provides a distinct visual experience while maintaining excellent readability.</p><h3 id="☁️-icloud-sync" tabindex="-1">☁️ <strong>iCloud Sync</strong> <a class="header-anchor" href="#☁️-icloud-sync" aria-label="Permalink to “☁️ iCloud Sync”">​</a></h3><p>Your settings, statistics, game saves, and daily challenge progress automatically sync across all your Apple devices via CloudKit. Start a game on your iPhone, continue on your Mac.</p><h3 id="🎮-game-center" tabindex="-1">🎮 <strong>Game Center</strong> <a class="header-anchor" href="#🎮-game-center" aria-label="Permalink to “🎮 Game Center”">​</a></h3><p>Compete on leaderboards with your best completion times, and earn achievements: First Solve, Easy Clear, Medium Clear, Hard Clear, Expert Clear, Master Clear, and Flawless (complete without hints or errors).</p><h3 id="🔇-clean-ad-free" tabindex="-1">🔇 <strong>Clean &amp; Ad-Free</strong> <a class="header-anchor" href="#🔇-clean-ad-free" aria-label="Permalink to “🔇 Clean &amp; Ad-Free”">​</a></h3><p>No interruptions, no pop-ups, no ads, no in-app purchases. Just pure, focused puzzle gameplay.</p><h3 id="🌍-25-languages" tabindex="-1">🌍 <strong>25 Languages</strong> <a class="header-anchor" href="#🌍-25-languages" aria-label="Permalink to “🌍 25 Languages”">​</a></h3><p>Switch languages at runtime from Settings without restarting the app. Supports English, Chinese (Simplified &amp; Traditional), Japanese, Korean, French, German, Spanish, Italian, Russian, Portuguese, Dutch, Vietnamese, Thai, Hindi, Turkish, Greek, Finnish, Norwegian, Danish, Hungarian, Indonesian, Malay, Ukrainian, and German (Switzerland).</p><h3 id="🔊-sound-effects" tabindex="-1">🔊 <strong>Sound Effects</strong> <a class="header-anchor" href="#🔊-sound-effects" aria-label="Permalink to “🔊 Sound Effects”">​</a></h3><p>Subtle sound effects for number placement, hints, errors, and victory — toggle on or off in Settings.</p><h3 id="🖨️-print-puzzles" tabindex="-1">🖨️ <strong>Print Puzzles</strong> <a class="header-anchor" href="#🖨️-print-puzzles" aria-label="Permalink to “🖨️ Print Puzzles”">​</a></h3><p>Print puzzles directly from the Mac app with difficulty selection and optional answer keys. Perfect for offline solving with pen and paper.</p><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to “System Requirements”">​</a></h2><ul><li><strong>iPhone/iPad</strong>: iOS/iPadOS 16.0 or later</li><li><strong>Mac</strong>: macOS 15.0 (Sequoia) or later (Apple Silicon)</li><li><strong>Storage</strong>: ~50 MB</li></ul><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to “Privacy”">​</a></h2><p>Sudoku is offline-first for core gameplay. All game data is stored locally and synced to your personal iCloud account only. No ads, no analytics, no third-party tracking. The only network features are iCloud sync, Game Center, and an optional &quot;More Apps&quot; section in Settings.</p><p>See the <a href="/guide/privacy.html">Privacy Policy</a> for details.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting Started”">​</a></h2><p>If you&#39;re new to Sudoku, start with the <a href="/guide/installation.html">Installation Guide</a> to get the app on your device.</p>`,43)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};